-- Generated by tools/quest_gate/new_quest.py from Quest Helper's
-- helpers/quests/bonevoyage/ -- docs/QUEST_SUITE_KIT.md phase 3.
-- Bone Voyage. Guide: quest-helper bonevoyage. Scripts: quest_bonevoyage/scripts/{bonevoyage,bv_voyage}.rs2.
--
-- Door rule (b71 re-drive): no goto departs from or lands in a closed space, and every gate,
-- boat and npc travel option between the player and the target is pressed, in and out.
-- Checked with test/quests/orchestrator/matthew-mbp-m4/reports/sample_tools/{reach,comp,locs_near}.py:
--   * Fresh start from Lumbridge 3206,3233 (no ::bonevoyage placement): Curator Haig's lobby
--     is open to the street (REACH closed-doors 376).
--   * The dig site region (the barge dock, the foreman, the Odd Old Man) is walled off from
--     Varrock by the vm_fencegate double gate 3296,3428-3429 (comp.py from 3364,3445: its edge
--     is that gate or the members' gate 3319,3467-3468). Every crossing presses the fence gate
--     (to_digsite / to_varrock, the same pass_door as itexam.lua and golem.lua).
--   * Both sawmill operators stand BEHIND a counter (fai_varrock_lumber_yard_counter): Varrock
--     3302,3491 north edge, operator 3302,3492 (m51_54.spawn), the room x 3301-3304 z 3492-3495
--     behind fai_varrock_locked_door; Hosidius 1624,3500 west edge, operator 1623,3500
--     (m25_54.spawn). The player stays on the customer side (3302,3491 / 1624,3500) and talks
--     across the counter.
--   * Great Kourend has no on-foot route: Veos's ship both ways (X Marks the Spot staged in setup:
--     xmarksthespot.rs2:32 sends the Sarim Veos to the Client of Kourend gate menu, whose "Can you take
--     me to Great Kourend?" sails; the Piscarilius Veos's "Can you take me somewhere?" sails back).
--   * Bone Voyage has no Woodcutting requirement, so no Woodcutting is staged: below 60 the guild's
--     wcguild_gater 1657,3504 pressed from outside (x 1658) runs the quest's own gate branch
--     (woodcutting_guild.rs2:23 -> bonevoyage.rs2 [label,bv_guild_gate]): a guild worker swaps the
--     proposal for the agreement at the gate (guide step talkToOperatorInGuildFromGate). The player
--     never enters the guild.
--   * The barge is boarded by the dock guard's Talk-to (bonevoyage.rs2 [label,bv_barge_guard_talk],
--     p_telejump to 3363,3453,1) and left by the deck guard's Disembark (op3, p_telejump to the
--     dock 3361,3446,0) on every visit; each landing is checked.
return {
    id = "bonevoyage",
    fixture = "fresh_lumbridge.ini",
    setup = {
        "::clearinv",
        "::give vodka 2",
        "::give marrentillvial 1",
        "::complete quest_digsite", -- start requirement
        "::setvar varb3637_vm_kudos 100", -- start requirement (100 Kudos)
        "::complete quest_xmarksthespot", -- Veos sails to Great Kourend only after it (xmarksthespot.rs2:32)
    },

    run = function(t)
        t.quest.bind({
            varp = "varb5795_fossilquest_progress",
            constants = {
                not_started = 0, foreman = 5, sawmill = 10, guild = 11, return_agree = 15,
                foreman2 = 20, lead = 21, jack = 22, lead2 = 23, items = 25, sail = 30,
                sail2 = 35, complete = 50,
            },
            display = "Bone Voyage",
            points = 1,
        })
        t.ticks(3)
        t.expect("quest.stage.not_started", t.quest.expect_stage("not_started"))

        local function here()
            local _, tl = t.world.tile()
            return tl
        end
        local function tile_str(tl)
            return tl and (tostring(tl.x) .. "," .. tostring(tl.z) .. "," .. tostring(tl.level)) or "nil"
        end

        -- The Varrock / dig-site fence gate (doors_selfstage.loc vm_fencegate_l/r): West = Varrock.
        local function to_varrock(prefix)
            t.exec("goto-" .. prefix .. ".fenceGate", t.player.goto_tile, 3298, 3429, 0)
            t.exec(prefix .. ".fenceGateWest", t.player.pass_door, { closed = "vm_fencegate_r",
                open = "vm_fencegate_r", at = { 3296, 3429, 0 }, near = { 3297, 3429 }, far = { 3294, 3429 } })
        end
        local function to_digsite(prefix)
            t.exec("goto-" .. prefix .. ".fenceGate", t.player.goto_tile, 3293, 3429, 0)
            t.exec(prefix .. ".fenceGateEast", t.player.pass_door, { closed = "vm_fencegate_r",
                open = "vm_fencegate_r", at = { 3296, 3429, 0 }, near = { 3294, 3429 }, far = { 3297, 3429 } })
        end

        -- The barge: Talk-to on the dock guard boards (p_telejump ^bv_lead_coord 3363,3453,1),
        -- Disembark (op3) on the deck guard lands on ^bv_dock_coord 3361,3446,0.
        local function board(step)
            t.exec("goto-" .. step, t.player.goto_tile, 3363, 3446, 0)
            t.exec(step, t.player.talk_to, "fossilquest_barge_guard_port_prequest", 1)
            t.exec(step .. "-dialog", t.chat.play, {
                "player:Can I go onto the barge?",
                "npc:Aye, go aboard.",
            })
            t.ticks(3)
            local tl = here()
            t.check(step .. ".landed", tl ~= nil and tl.level == 1 and math.abs(tl.x - 3363) <= 2 and math.abs(tl.z - 3453) <= 2,
                "boarded the museum barge at " .. tile_str(tl) .. " (want 3363,3453,1)")
        end
        local function disembark(step)
            t.exec(step, t.player.talk_to, "fossilquest_barge_guard_barge", 3)
            t.ticks(3)
            local tl = here()
            t.check(step .. ".landed", tl ~= nil and tl.level == 0 and math.abs(tl.x - 3361) <= 1 and math.abs(tl.z - 3446) <= 1,
                "disembarked at the Digsite dock " .. tile_str(tl) .. " (want 3361,3446,0)")
        end

        -- Veos: Port Sarim <-> Port Piscarilius (veos_ferry.rs2).
        local function veos_to_kourend(step)
            t.exec("goto-" .. step, t.player.goto_tile, 3054, 3246, 0)
            t.exec(step, t.player.talk_to, "veos_sarim", 1)
            t.exec(step .. "-menu", t.chat.drain, { stop_at = "options" })
            t.exec(step .. "-sail", t.chat.choose, "Can you take me to Great Kourend?")
            t.exec(step .. "-done", t.chat.drain, {})
            t.ticks(4)
            local tl = here()
            t.check(step .. "-landed", tl ~= nil and tl.level == 0 and math.abs(tl.x - 1824) <= 3 and math.abs(tl.z - 3690) <= 3,
                "landed at the Piscarilius dock at " .. tile_str(tl) .. " (want 1824,3690,0)")
        end
        local function veos_to_sarim(step)
            t.exec("goto-" .. step, t.player.goto_tile, 1824, 3690, 0)
            t.exec(step, t.player.talk_to, "veos", 1)
            t.exec(step .. "-menu", t.chat.drain, { stop_at = "options" })
            t.exec(step .. "-somewhere", t.chat.choose, "Can you take me somewhere?")
            t.exec(step .. "-where", t.chat.drain, { stop_at = "options" })
            t.exec(step .. "-sail", t.chat.choose, "Travel to Port Sarim.")
            t.exec(step .. "-done", t.chat.drain, {})
            t.ticks(4)
            local tl = here()
            t.check(step .. "-landed", tl ~= nil and tl.level == 0 and math.abs(tl.x - 3055) <= 3 and math.abs(tl.z - 3245) <= 3,
                "landed at the Port Sarim dock at " .. tile_str(tl) .. " (want 3055,3245,0)")
        end

        t.exec("goto-talkToHaig", t.player.goto_tile, 3257, 3448, 0)
        t.exec("talkToHaig", t.player.talk_to, "curator", 1)
        t.exec("talkToHaig-dialog", t.chat.play, {
            "npc:Welcome to the museum of Varro",
            "choose:Have you any interesting news?",
            "player:Have you any interesting news",
            "npc:As a matter of fact",
            "choose:Yes.",
            "player:Yes.",
            "npc:Speak to the Barge Foreman",
        })
        t.ticks(2)
        -- Bone Voyage's requirements are The Dig Site and 100 Kudos only (OSRS Wiki Bone_Voyage
        -- oldid 15364304 |requirements; Quest Helper BoneVoyage.getGeneralRequirements). No
        -- Woodcutting is staged, so this stage check is also the proof that Haig starts the
        -- quest below 60 Woodcutting.
        t.expect("quest.stage.foreman", t.quest.expect_stage("foreman"))

        to_digsite("talkToForeman")
        t.exec("goto-talkToForeman", t.player.goto_tile, 3364, 3444, 0)
        t.exec("talkToForeman", t.player.talk_to, "vm_canal_barge_foremen_talking", 1)
        t.exec("talkToForeman-dialog", t.chat.play, {
            "player:Curator Haig sent me",
            "npc:We need lumber from the sawmills",
        })
        t.ticks(2)
        t.expect("quest.stage.sawmill", t.quest.expect_stage("sawmill"))

        -- Across the counter from the lumber yard's customer side.
        to_varrock("talkToSawmillOperator")
        t.exec("goto-talkToSawmillOperator", t.player.goto_tile, 3302, 3491, 0)
        t.exec("talkToSawmillOperator", t.player.talk_to, "poh_sawmill_opp", 1, { at = { 3302, 3492 } })
        t.exec("talkToSawmillOperator-dialog", t.chat.play, {
            "player:I'm here on behalf of the museum archaeological team.",
            "npc:Take this proposal to the Woodcutting Guild",
        })
        t.ticks(2)
        t.expect("quest.stage.guild", t.quest.expect_stage("guild"))
        t.check("proposal-held", t.inv.expect_has("fossilquest_sawmill_proposal", 1), "sawmill proposal in the backpack")

        -- Port Sarim -> Veos -> Piscarilius -> overland to the Woodcutting Guild's east gate.
        veos_to_kourend("travelToKourend")
        t.exec("goto-talkToOperatorInGuildFromGate", t.player.goto_tile, 1658, 3504, 0)
        t.exec("talkToOperatorInGuildFromGate", t.player.click_loc, "wcguild_gater", 1, { at = { 1657, 3504, 0 } })
        t.exec("talkToOperatorInGuildFromGate-dialog", t.chat.play, {
            "mesbox:A guild sawmill worker takes the proposal",
            "mesbox:You receive a sawmill agreement",
        })
        t.ticks(2)
        t.expect("quest.stage.return_agree", t.quest.expect_stage("return_agree"))
        t.check("agreement-held", t.inv.expect_has("fossilquest_sawmill_agreement", 1), "sawmill agreement in the backpack")
        t.exec("proposal-gone", t.inv.expect_absent, "fossilquest_sawmill_proposal")
        do
            local tl = here()
            t.check("talkToOperatorInGuildFromGate.outside", tl ~= nil and tl.x >= 1658 and tl.level == 0,
                "still outside the guild gate at " .. tile_str(tl) .. " (below 60 Woodcutting the gate does not open)")
        end

        -- Veos back to Port Sarim, overland to the lumber yard.
        veos_to_sarim("travelToSarim")
        t.exec("goto-returnWithAgreement", t.player.goto_tile, 3302, 3491, 0)
        t.exec("returnWithAgreement", t.player.talk_to, "poh_sawmill_opp", 1, { at = { 3302, 3492 } })
        t.exec("returnWithAgreement-dialog", t.chat.play, {
            "player:I'm here on behalf of the museum archaeological team.",
            "npc:This agreement will do",
        })
        t.ticks(2)
        t.expect("quest.stage.foreman2", t.quest.expect_stage("foreman2"))

        to_digsite("talkToForemanAgain")
        t.exec("goto-talkToForemanAgain", t.player.goto_tile, 3364, 3444, 0)
        t.exec("talkToForemanAgain", t.player.talk_to, "vm_canal_barge_foremen_talking", 1)
        t.exec("talkToForemanAgain-dialog", t.chat.play, {
            "player:I've secured the sawmill agreement.",
            "npc:Excellent. Board the barge",
        })
        t.ticks(2)
        t.expect("quest.stage.lead", t.quest.expect_stage("lead"))

        board("boardBarge")
        t.exec("talkToNavigator", t.player.talk_to, "fossilquest_lead_navigator_quest", 1)
        t.exec("talkToNavigator-dialog", t.chat.play, {
            "player:Yep, that would be me.",
            "npc:We need advice on cursed voyages",
            "player:No, what happened?",
            "npc:Seasickness and bad luck",
        })
        t.ticks(2)
        t.expect("quest.stage.jack", t.quest.expect_stage("jack"))

        -- Off the barge, through the fence gate, overland to the Rusty Anchor (open doorway).
        disembark("talkToJack.disembark")
        to_varrock("talkToJack")
        t.exec("goto-talkToJack", t.player.goto_tile, 3047, 3256, 0)
        t.exec("talkToJack", t.player.talk_to, "sarim_pub_drinker_1", 1)
        t.exec("talkToJack-dialog", t.chat.play, {
            "player:Ever made any cursed voyages?",
            "npc:Aye",
        })
        t.ticks(2)
        t.expect("quest.stage.lead2", t.quest.expect_stage("lead2"))

        to_digsite("boardBargeAfterJack")
        board("boardBargeAfterJack")
        t.exec("talkToNavigatorAgain", t.player.talk_to, "fossilquest_lead_navigator_quest", 1)
        t.exec("talkToNavigatorAgain-dialog", t.chat.play, {
            "player:Jack Seagull mentioned",
            "npc:Fetch a bone charm",
        })
        t.ticks(2)
        t.expect("quest.stage.items", t.quest.expect_stage("items"))

        -- The Odd Old Man is on the dig-site side of the fence (REACH closed-doors from the dock).
        disembark("talkToOddOldMan.disembark")
        t.exec("goto-talkToOddOldMan", t.player.goto_tile, 3360, 3504, 0)
        t.exec("talkToOddOldMan", t.player.talk_to, "rag_odd_old_man", 1)
        t.exec("talkToOddOldMan-dialog", t.chat.play, {
            "player:Talk about lucky charms.",
            "player:I'm making a cursed voyage.",
            "npc:A bone charm",
        })
        t.check("bone-charm-held", t.inv.await("fossilquest_bone_charm", 1, 5), "bone charm from the Odd Old Man")

        to_varrock("talkToApoth")
        t.exec("goto-talkToApoth", t.player.goto_tile, 3195, 3404, 0)
        t.exec("talkToApoth", t.player.talk_to, "apothecary", 1)
        t.exec("talkToApoth-dialog", t.chat.play, {
            "player:Talk about Bone Voyage.",
            "npc:Sealegs, eh?",
        })
        t.exec("talkToApothAgain", t.player.talk_to, "apothecary", 1)
        t.exec("talkToApothAgain-dialog", t.chat.play, {
            "npc:Here's a potion of sealegs",
        })
        t.check("potion-held", t.inv.await("fossilquest_potion", 1, 5), "potion of sealegs from the Apothecary")

        to_digsite("boardBargeWithPotionAndCharm")
        board("boardBargeWithPotionAndCharm")
        t.exec("giveJuniorBone", t.player.talk_to, "fossilquest_jr_navigator_quest", 1)
        t.exec("giveJuniorBone-dialog", t.chat.play, {
            "player:I brought a bone charm.",
            "npc:Perfect!",
        })
        t.exec("giveLeadPotion", t.player.talk_to, "fossilquest_lead_navigator_quest", 1)
        t.exec("giveLeadPotion-dialog", t.chat.play, {
            "player:I brought a potion of sealegs.",
            "npc:That should settle my stomach",
        })
        t.ticks(2)
        t.expect("quest.stage.sail", t.quest.expect_stage("sail"))

        -- Guide step boardBargeToSail is shown off the barge: step ashore and board again.
        disembark("boardBargeToSail.disembark")
        board("boardBargeToSail")
        t.exec("navigateShip", t.player.talk_to, "fossilquest_lead_navigator_quest", 1)
        t.exec("navigateShip-dialog", t.chat.play, {
            "npc:We're all set",
            "player:I'm ready, let's go.",
            "npc:Keep her steady",
        })
        t.expect("voyage-open", t.ui.await_open("fossilquest_sailing", 25))
        local _, left_w = t.ui.widget("fossilquest_sailing:direction_left")
        local _, right_w = t.ui.widget("fossilquest_sailing:direction_right")
        local _, up_w = t.ui.widget("fossilquest_sailing:throttle_increase")
        t.check("voyage-widgets", left_w ~= nil and right_w ~= nil and up_w ~= nil, "steer left " .. tostring(left_w) .. " right " .. tostring(right_w) .. " throttle+ " .. tostring(up_w))
        t.ui.invoke(up_w, 1)
        local steered = 0
        local last_bearing = -1
        for _ = 1, 400 do
            local _, stage = t.var.server("varb5795_fossilquest_progress")
            if stage ~= 30 then break end
            local _, bearing = t.var.server("varp7220_bv_voy_bearing")
            last_bearing = bearing
            if bearing < 4 then
                t.ui.invoke(right_w, 1)
                steered = steered + 1
            elseif bearing > 4 then
                t.ui.invoke(left_w, 1)
                steered = steered + 1
            end
            t.ticks(1)
        end
        t.check("voyage-steered", steered > 0, "steered " .. steered .. " times, last bearing " .. tostring(last_bearing))
        t.ticks(5)
        t.expect("quest.stage.complete", t.quest.expect_stage("complete"))
        local snapshot = t.skill.snapshot()
        t.exec("note-book-reward", t.inv.has, "fossil_note_book")
        t.quest.expect_complete()
        t.finish(0)
    end,
}
